// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 blockNumberOffset, uint256 warpDelta) public {
        vm.assume(caller != address(0));

        uint256 targetBlock = bound(blockNumberOffset, 1, 1000);

        uint256 delta = bound(warpDelta, 1, 1 days);

        vm.deal(caller, 20 ether);

        vm.roll(targetBlock);

        vm.warp(block.timestamp + delta);

        vm.startPrank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}('');
        vm.stopPrank();

        bool expectedEmpty = (block.number % 15 == 0);

        assertTrue((address(c).balance == 0) == expectedEmpty);
    }
}
